function atualizarValores({ min, media, max, chance }) {
    const fatorAleatorio = () => 1 + Math.random() * 0.2 - 0.1; // varia entre -0.1 e +0.1

    return {
        min: min * fatorAleatorio(),
        media: media * fatorAleatorio(),
        max: max * fatorAleatorio(),
        chance: Math.max(1, Math.min(100, chance + Math.floor(Math.random() * 10 - 5)))
    };
}


