            resposta += `• *Mínimo:* R$ ${dados.min.toFixed(2)}\n`;
            resposta += `• *Média:* R$ ${dados.media.toFixed(2)}\n`;
            resposta += `• *Máximo:* R$ ${dados.max.toFixed(2)}\n`;
            resposta += `• *Chance:* ${dados.chance}%\n\n`;
        });

        return resposta + "Observação: As porcentagens podem conter alguma divergência...\n";
    }

    // Caso específico: um único jogo
    const jogoData = jogos[jogo];
    if (!jogoData) {
        return `❌ Jogo "${jogo}" não encontrado.`;
    }

    const dados = atualizarValores(jogoData);

